CREATE TABLE time_recaps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),room_id uuid NOT NULL REFERENCES rooms(id),actor_id uuid NOT NULL REFERENCES world_characters(id),run_id uuid NOT NULL REFERENCES runs(id),state text NOT NULL CHECK(state IN ('running','succeeded','failed','unknown')),content jsonb,remaining integer NOT NULL DEFAULT 0 CHECK(remaining BETWEEN 0 AND 2),usage jsonb,error_code text,payload_hash text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(run_id,actor_id));
CREATE TABLE run_recap_refs(run_id uuid NOT NULL REFERENCES runs(id),actor_id uuid NOT NULL REFERENCES world_characters(id),recap_id uuid NOT NULL REFERENCES time_recaps(id) ON DELETE CASCADE,consumed boolean NOT NULL DEFAULT false,PRIMARY KEY(run_id,actor_id));
